<#
.SYNOPSIS
    Intune Win32 app install script for Claude Desktop (direct-download MSIX).

.DESCRIPTION
    Installs the Claude Desktop .msix, from one of two sources:

      - Bundled: a Claude*.msix packaged alongside this script in the
        .intunewin (or passed via -MsixPath).
      - Downloaded: when no MSIX is bundled, the script downloads the current
        Claude Desktop release for the device's architecture from Anthropic's
        official download endpoint, verifies its Authenticode signature and
        package identity, installs it, and deletes the download. This keeps
        the .intunewin tiny (scripts only) and means newly enrolled devices
        always install the latest release - no periodic re-wrapping needed.
        Requires the device to reach claude.ai and downloads.claude.ai at
        install time.

    Supports both deployment contexts:

      - Machine / SYSTEM (device assignment): provisions the package for all
        users with Add-AppxProvisionedPackage. Existing users get the package
        registered at their next sign-in; new users get it at first sign-in.
      - User (user assignment): registers the package for the signing-in user
        with Add-AppxPackage.

    The script is idempotent and migration-friendly: if Claude is already
    installed at a version equal to or newer than the one being installed (for
    example because Claude's auto-updater has already moved the device forward,
    or the device previously had the MSIX deployed as a line-of-business app),
    it exits 0 without attempting a downgrade. In download mode the version
    check happens before the download, so devices that are already current
    never pull the package at all.

.PARAMETER MsixPath
    Path to a Claude .msix to install. Defaults to the single Claude*.msix
    next to this script, if present; otherwise the script downloads the
    current release.

.PARAMETER Scope
    Auto (default), Machine, or User. Auto selects Machine when running as
    SYSTEM (the Intune "system" install behavior) and User otherwise.

.PARAMETER Architecture
    Auto (default), x64, or arm64. Only used in download mode; Auto matches
    the device's native architecture.

.NOTES
    Targets Windows PowerShell 5.1 (what the Intune Management Extension uses).
    Logs to %TEMP% (C:\Windows\Temp when running as SYSTEM).

    These scripts are maintained by Anthropic; the latest version is linked
    from the Claude Desktop Windows deployment guide on support.claude.com.
#>

[CmdletBinding()]
param(
    [string]$MsixPath,

    [ValidateSet("Auto", "Machine", "User")]
    [string]$Scope = "Auto",

    [ValidateSet("Auto", "x64", "arm64")]
    [string]$Architecture = "Auto",

    # Optional hard pin: SHA-1 thumbprint of the expected Authenticode leaf
    # certificate. Must be updated when Anthropic's signing certificate is
    # renewed. The default publisher-identity pin survives renewals (the
    # subject DN is stable per MSIX persistent-identity rules). Applies to
    # downloaded packages always, and to a bundled/-MsixPath package when set.
    [string]$ExpectedSignerThumbprint
)

$PackageName = "Claude"
# The publisher-hash suffix of the PackageFamilyName. Matching on the family
# name (not just the name) means a third-party package that happens to call
# itself "Claude" under a different signing publisher is never counted.
$PublisherId = "pzs8sxrjxfjjc"
$PackageFamilyName = "${PackageName}_${PublisherId}"

$ErrorActionPreference = "Stop"
# PS 5.1 defaults to TLS 1.0; the download endpoints require TLS 1.2+.
[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12

# ----------------------------------------------------------------------------
# Relaunch in 64-bit PowerShell if we were started in a 32-bit host (the Intune
# Management Extension is a 32-bit process).
# ----------------------------------------------------------------------------
if ($env:PROCESSOR_ARCHITEW6432 -and -not [Environment]::Is64BitProcess) {
    $sysnativePowerShell = Join-Path $env:windir "sysnative\WindowsPowerShell\v1.0\powershell.exe"
    if (Test-Path $sysnativePowerShell) {
        $relaunchArgs = @(
            "-NoProfile", "-ExecutionPolicy", "Bypass",
            "-File", $MyInvocation.MyCommand.Path,
            "-Scope", $Scope,
            "-Architecture", $Architecture
        )
        if ($MsixPath) { $relaunchArgs += @("-MsixPath", $MsixPath) }
        if ($ExpectedSignerThumbprint) { $relaunchArgs += @("-ExpectedSignerThumbprint", $ExpectedSignerThumbprint) }
        & $sysnativePowerShell @relaunchArgs
        exit $LASTEXITCODE
    }
}

function Test-IsSystemContext {
    $identity = [System.Security.Principal.WindowsIdentity]::GetCurrent()
    return $identity.IsSystem
}

$resolvedScope = $Scope
if ($resolvedScope -eq "Auto") {
    $resolvedScope = if (Test-IsSystemContext) { "Machine" } else { "User" }
}

$resolvedArchitecture = $Architecture
if ($resolvedArchitecture -eq "Auto") {
    # After the 64-bit relaunch above, PROCESSOR_ARCHITECTURE is the native one.
    $resolvedArchitecture = if ($env:PROCESSOR_ARCHITECTURE -eq "ARM64") { "arm64" } else { "x64" }
}

# Log to %TEMP% (C:\Windows\Temp in SYSTEM context). Deliberately NOT a
# pre-creatable directory under %ProgramData%: a standard user could plant a
# directory junction there ahead of time and turn this SYSTEM-context
# transcript into an arbitrary file write. The random suffix keeps the name
# unpredictable, and a transcript failure must never fail the deployment.
$logFile = Join-Path $env:TEMP ("Claude-Intune-Install-{0:yyyyMMdd-HHmmss}-{1}.log" -f (Get-Date), ([System.IO.Path]::GetRandomFileName() -replace "\.", ""))
try { Start-Transcript -Path $logFile -Force | Out-Null } catch {}

function Write-Log {
    param([string]$Message)
    Write-Output ("[{0:u}] {1}" -f (Get-Date), $Message)
}

function Get-InstalledClaudeVersion {
    $versions = @()
    try {
        $packages = if ($resolvedScope -eq "Machine") {
            Get-AppxPackage -Name $PackageName -AllUsers -ErrorAction SilentlyContinue
        } else {
            Get-AppxPackage -Name $PackageName -ErrorAction SilentlyContinue
        }
        $packages = $packages | Where-Object { $_.PackageFamilyName -eq $PackageFamilyName }
        if ($packages) { $versions += @($packages | ForEach-Object { $_.Version }) }
    } catch {}

    if ($resolvedScope -eq "Machine") {
        try {
            $provisioned = Get-AppxProvisionedPackage -Online -ErrorAction SilentlyContinue |
                Where-Object { $_.DisplayName -eq $PackageName -and $_.PackageName -like "*__$PublisherId" }
            if ($provisioned) { $versions += @($provisioned | ForEach-Object { $_.Version }) }
        } catch {}
    }

    if ($versions.Count -eq 0) { return $null }
    return ($versions | ForEach-Object { [version]$_ } | Sort-Object -Descending | Select-Object -First 1)
}

function Get-ProvisionedClaudeVersion {
    # Machine-wide (staged) copy only — used by the Machine-scope idempotency
    # check, where a per-user registration must not count.
    try {
        $provisioned = Get-AppxProvisionedPackage -Online -ErrorAction SilentlyContinue |
            Where-Object { $_.DisplayName -eq $PackageName -and $_.PackageName -like "*__$PublisherId" }
        if ($provisioned) {
            return ($provisioned | ForEach-Object { [version]$_.Version } | Sort-Object -Descending | Select-Object -First 1)
        }
    } catch {}
    return $null
}

function Get-MsixIdentity {
    param([string]$Path)
    # Read Package/Identity (@Version, @Publisher) straight out of AppxManifest.xml inside the .msix.
    Add-Type -AssemblyName System.IO.Compression.FileSystem
    $zip = [System.IO.Compression.ZipFile]::OpenRead($Path)
    try {
        $entry = $zip.Entries | Where-Object { $_.FullName -eq "AppxManifest.xml" } | Select-Object -First 1
        if (-not $entry) { throw "AppxManifest.xml not found in $Path" }
        $reader = New-Object System.IO.StreamReader($entry.Open())
        try {
            [xml]$manifest = $reader.ReadToEnd()
        } finally {
            $reader.Dispose()
        }
        return [pscustomobject]@{
            Version   = [version]$manifest.Package.Identity.Version
            Publisher = [string]$manifest.Package.Identity.Publisher
        }
    } finally {
        $zip.Dispose()
    }
}

function Get-MsixVersion {
    param([string]$Path)
    return (Get-MsixIdentity -Path $Path).Version
}

function Get-MsixPublisherId {
    # The publisher-hash suffix Windows derives for a PackageFamilyName:
    # first 8 bytes of SHA-256(UTF-16LE(publisher DN)), Crockford base32.
    param([string]$Publisher)
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try {
        $hash = $sha.ComputeHash([System.Text.Encoding]::Unicode.GetBytes($Publisher))
    } finally {
        $sha.Dispose()
    }
    $bits = ""
    foreach ($b in $hash[0..7]) { $bits += [Convert]::ToString($b, 2).PadLeft(8, "0") }
    $bits += "0"
    $alphabet = "REDACTED"
    $out = ""
    for ($i = 0; $i -lt 65; $i += 5) {
        $out += $alphabet[[Convert]::ToInt32($bits.Substring($i, 5), 2)]
    }
    return $out
}

function Resolve-LatestClaudeMsix {
    # Resolves the official "latest release" redirect WITHOUT downloading,
    # returning the direct package URL plus the version parsed from its path
    # (.../releases/win32/<arch>/<version>/Claude-<hash>.msix). The version
    # lets us skip the multi-hundred-MB download entirely on devices that are
    # already current.
    param([string]$Arch)
    $redirectUrl = "https://claude.ai/api/desktop/win32/$Arch/msix/latest/redirect"
    $request = [System.Net.WebRequest]::Create($redirectUrl)
    # GET, not HEAD (the endpoint rejects HEAD with 405). With redirects
    # disabled, the response is just the 3xx itself — no package body.
    $request.Method = "GET"
    $request.AllowAutoRedirect = $false
    $response = $request.GetResponse()
    try {
        $location = $response.Headers["Location"]
    } finally {
        $response.Close()
    }
    if (-not $location) {
        throw "Expected a redirect from $redirectUrl but did not get a Location header."
    }
    if ($location -notmatch '^https://') {
        throw "Unexpected non-HTTPS redirect target from $redirectUrl : $location"
    }
    $version = $null
    if ($location -match '/(\d+(?:\.\d+){1,3})/[^/]*\.msix') {
        try { $version = [version]$Matches[1] } catch {}
    }
    return [pscustomobject]@{ Url = $location; Version = $version }
}

function Save-RemoteMsix {
    param([string]$Url)
    $dest = Join-Path $env:TEMP ("Claude-Intune-Download-{0}.msix" -f ([System.IO.Path]::GetRandomFileName() -replace "\.", ""))
    # Invoke-WebRequest's progress rendering slows large downloads badly on
    # PS 5.1 — suppress it for the transfer.
    $previousProgressPreference = $ProgressPreference
    $ProgressPreference = "SilentlyContinue"
    try {
        $attempt = 0
        while ($true) {
            $attempt++
            try {
                Invoke-WebRequest -UseBasicParsing -Uri $Url -OutFile $dest
                break
            } catch {
                Remove-Item -Path $dest -Force -ErrorAction SilentlyContinue
                if ($attempt -ge 3) { throw }
                Write-Log "Download attempt $attempt failed: $($_.Exception.Message). Retrying..."
                Start-Sleep -Seconds (5 * $attempt)
            }
        }
    } finally {
        $ProgressPreference = $previousProgressPreference
    }
    return $dest
}

function Assert-MsixIsAuthentic {
    # Defense in depth for downloaded packages: Add-AppxProvisionedPackage /
    # Add-AppxPackage enforce a trusted signature anyway, but checking here
    # gives a clear error and never hands an unexpected file to the deployment
    # stack at all.
    param([string]$Path)
    $signature = Get-AuthenticodeSignature -FilePath $Path
    if ($signature.Status -ne "Valid") {
        throw "MSIX at $Path failed Authenticode validation (status: $($signature.Status))."
    }
    if ($ExpectedSignerThumbprint) {
        $expected = ($ExpectedSignerThumbprint -replace "[^0-9A-Fa-f]", "")
        if ($signature.SignerCertificate.Thumbprint -ne $expected) {
            throw "MSIX at $Path signer thumbprint $($signature.SignerCertificate.Thumbprint) does not match -ExpectedSignerThumbprint $expected."
        }
    }
    # Pin the package to Claude's exact publisher identity, not a substring of
    # the signer name (any CA-issued cert merely *containing* 'Anthropic, PBC'
    # would pass a substring match). Windows refuses to install an MSIX whose
    # Identity Publisher differs from the signing certificate's subject, so
    # family-hash equality here binds the trusted-chain signer to Anthropic's
    # exact publisher DN before the file reaches the deployment stack.
    $publisher = (Get-MsixIdentity -Path $Path).Publisher
    $actualId = Get-MsixPublisherId -Publisher $publisher
    if ($actualId -ne $PublisherId) {
        throw "MSIX at $Path publisher '$publisher' (family suffix $actualId) is not Claude's expected publisher (family suffix $PublisherId). Signer: $($signature.SignerCertificate.Subject)."
    }
}

$downloadedMsix = $null
$exitCode = 0
try {
    Write-Log "Starting Claude Desktop install. Scope=$resolvedScope User=$([System.Security.Principal.WindowsIdentity]::GetCurrent().Name)"

    # Resolve the .msix to install: explicit -MsixPath, else a bundled
    # Claude*.msix next to the script, else download the current release.
    if (-not $MsixPath) {
        $candidates = @(Get-ChildItem -Path $PSScriptRoot -Filter "Claude*.msix" -ErrorAction SilentlyContinue)
        if ($candidates.Count -gt 1) {
            # Refuse to guess: alphabetical order can silently pick an older
            # build (Claude-1.9 sorts before Claude-1.10).
            throw "Multiple Claude*.msix files found next to the script ($($candidates.Name -join ', ')). Package exactly one MSIX into the .intunewin, or pass -MsixPath explicitly."
        }
        if ($candidates.Count -eq 1) {
            $MsixPath = $candidates[0].FullName
        }
    }

    if ($MsixPath) {
        if (-not (Test-Path $MsixPath)) {
            throw "MSIX not found at $MsixPath"
        }
        Write-Log "Using local MSIX: $MsixPath"
        if ($ExpectedSignerThumbprint) {
            # Bundled packages are admin-authored and normally trusted as-is;
            # an explicit pin is a request to verify this one too.
            Write-Log "Verifying bundled MSIX (signer pin requested)."
            Assert-MsixIsAuthentic -Path $MsixPath
        }
    } else {
        # Download mode.
        $latest = Resolve-LatestClaudeMsix -Arch $resolvedArchitecture
        Write-Log "No bundled MSIX. Latest $resolvedArchitecture release: $(if ($latest.Version) { $latest.Version } else { '<unknown version>' })"

        # Skip the download entirely when this scope is already current.
        $currentBeforeDownload = if ($resolvedScope -eq "Machine") { Get-ProvisionedClaudeVersion } else { Get-InstalledClaudeVersion }
        if ($currentBeforeDownload -and $latest.Version -and $currentBeforeDownload -ge $latest.Version) {
            Write-Log "Claude $currentBeforeDownload is already $(if ($resolvedScope -eq 'Machine') { 'provisioned' } else { 'installed' }) at >= the latest release. Nothing to do."
            exit 0
        }

        Write-Log "Downloading $($latest.Url)"
        $downloadedMsix = Save-RemoteMsix -Url $latest.Url
        Write-Log "Downloaded $([math]::Round((Get-Item $downloadedMsix).Length / 1MB)) MB. Verifying signature."
        Assert-MsixIsAuthentic -Path $downloadedMsix
        $MsixPath = $downloadedMsix
    }

    $packageVersion = Get-MsixVersion -Path $MsixPath
    $installedVersion = Get-InstalledClaudeVersion
    Write-Log "Package version: $packageVersion. Installed version: $(if ($installedVersion) { $installedVersion } else { '<none>' })."

    # Idempotency / no-downgrade check. In Machine scope this looks at the
    # *provisioned* copy specifically: a per-user install that happens to be
    # >= the baseline must not skip machine-wide provisioning, or new users on
    # the device would never get Claude.
    $currentForScope = if ($resolvedScope -eq "Machine") { Get-ProvisionedClaudeVersion } else { $installedVersion }
    if ($currentForScope -and $currentForScope -ge $packageVersion) {
        # Already current (likely via Claude's auto-updater, or a prior LOB
        # deployment). Never downgrade; report success so detection takes over.
        Write-Log "Claude $currentForScope is already $(if ($resolvedScope -eq 'Machine') { 'provisioned' } else { 'installed' }) at >= the packaged version. Nothing to do."
        exit 0
    }

    if ($resolvedScope -eq "Machine") {
        Write-Log "Provisioning $MsixPath for all users (Add-AppxProvisionedPackage)."
        Add-AppxProvisionedPackage -Online -PackagePath $MsixPath -SkipLicense | Out-Null
        Write-Log "Provisioned. Existing signed-in users will get the package registered at next sign-in."
    } else {
        Write-Log "Installing $MsixPath for the current user (Add-AppxPackage)."
        # -ForceApplicationShutdown: Intune pushes silently while users work; a
        # running Claude would otherwise fail the upgrade with 0x80073D02.
        # Note: registering this package requires elevation (it declares a
        # LocalSystem packaged service for Cowork) — see README install-behavior
        # guidance.
        Add-AppxPackage -Path $MsixPath -ForceApplicationShutdown
        Write-Log "Installed for current user."
    }

    $finalVersion = Get-InstalledClaudeVersion
    Write-Log "Install complete. Detected version after install: $(if ($finalVersion) { $finalVersion } else { '<none>' })."
} catch {
    $message = $_.Exception.Message
    # 0x80073D06: a newer version is already installed. Treat as success — the
    # device is ahead of the packaged baseline (auto-updater already ran).
    if ($message -match "0x80073D06") {
        Write-Log "A newer version of Claude is already installed (0x80073D06). Treating as success."
        $exitCode = 0
    } else {
        Write-Log "ERROR: $message"
        $exitCode = 1
    }
} finally {
    if ($downloadedMsix) {
        Remove-Item -Path $downloadedMsix -Force -ErrorAction SilentlyContinue
    }
    try { Stop-Transcript | Out-Null } catch {}
}

exit $exitCode

